import socket
import struct
import threading
import hashlib
import os

# Redis-compatible protocol parser for lightweight cache service
class MiniCacheServer:
    def __init__(self, host='0.0.0.0', port=6380, data_dir='/var/cache/minicache'):
        self.host = host
        self.port = port
        self.data_dir = data_dir
        self.store = {}
        self.auth_token = os.environ.get('CACHE_AUTH_TOKEN', '')
        self.authenticated_clients = set()

    def handle_client(self, conn, addr):
        client_id = f"{addr[0]}:{addr[1]}"
        buf = b''
        try:
            while True:
                data = conn.recv(4096)
                if not data:
                    break
                buf += data
                while b'\r\n' in buf:
                    line, buf = buf.split(b'\r\n', 1)
                    response = self.process_command(line.decode('utf-8', errors='replace'), client_id)
                    conn.sendall(response.encode() + b'\r\n')
        except Exception as e:
            pass
        finally:
            self.authenticated_clients.discard(client_id)
            conn.close()

    def process_command(self, cmd_line, client_id):
        parts = cmd_line.strip().split(' ', 2)
        if not parts:
            return '-ERR empty command'
        command = parts[0].upper()

        if command == 'AUTH':
            if len(parts) < 2:
                return '-ERR wrong number of arguments'
            if parts[1] == self.auth_token:
                self.authenticated_clients.add(client_id)
                return '+OK'
            return '-ERR invalid password'

        if command == 'PING':
            return '+PONG'

        # Commands below require auth if token is set
        if self.auth_token and client_id not in self.authenticated_clients:
            return '-NOAUTH Authentication required'

        if command == 'SET':
            if len(parts) < 3:
                return '-ERR wrong number of arguments'
            key = parts[1]
            value = parts[2]
            self.store[key] = value
            return '+OK'

        elif command == 'GET':
            if len(parts) < 2:
                return '-ERR wrong number of arguments'
            key = parts[1]
            val = self.store.get(key)
            if val is None:
                return '$-1'
            return f'${len(val)}\r\n{val}'

        elif command == 'SAVE':
            return self._persist_to_disk()

        elif command == 'CONFIG':
            if len(parts) >= 3 and parts[1].upper() == 'SET':
                # Allow runtime config changes
                kv = parts[2].split('=', 1)
                if len(kv) == 2:
                    config_key, config_val = kv
                    if config_key == 'data_dir':
                        self.data_dir = config_val
                        return '+OK'
                    elif config_key == 'auth_token':
                        self.auth_token = config_val
                        return '+OK'
            return '-ERR unknown config parameter'

        elif command == 'EVAL':
            # Lua-like eval for computed keys (simplified)
            if len(parts) < 2:
                return '-ERR wrong number of arguments'
            expr = parts[1] if len(parts) == 2 else parts[2]
            try:
                # Restricted eval for arithmetic expressions on stored values
                result = eval(expr, {"__builtins__": {}}, self.store)
                return f'+{result}'
            except Exception as e:
                return f'-ERR {str(e)}'

        return '-ERR unknown command'

    def _persist_to_disk(self):
        try:
            os.makedirs(self.data_dir, exist_ok=True)
            dump_path = os.path.join(self.data_dir, 'dump.mcdb')
            with open(dump_path, 'w') as f:
                for k, v in self.store.items():
                    f.write(f'{k}\t{v}\n')
            return '+OK'
        except Exception as e:
            return f'-ERR {str(e)}'

    def start(self):
        srv = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        srv.bind((self.host, self.port))
        srv.listen(32)
        while True:
            conn, addr = srv.accept()
            t = threading.Thread(target=self.handle_client, args=(conn, addr))
            t.daemon = True
            t.start()

if __name__ == '__main__':
    server = MiniCacheServer()
    server.start()
